import { test, expect } from '@playwright/test';

test.describe('Shopping Cart Badge and Add/Remove Product', () => {
  test.beforeEach(async ({ page }) => {
    // Navigate to the Sauce Demo website
    await page.goto('https://www.saucedemo.com');

    // Log in with standard_user credentials
    await page.getByLabel('Username').fill('standard_user');
    await page.getByLabel('Password').fill('secret_sauce');
    await page.getByRole('button', { name: /login/i }).click();

    // Wait for the inventory page to load
    await page.waitForURL('**/inventory.html');
  });

  test('should add product to cart and display badge with count 1', async ({ page }) => {
    // Click the add to cart button for Sauce Labs Backpack
    const addToCartButton = page.locator('[data-test="add-to-cart-sauce-labs-backpack"]');
    await addToCartButton.click();

    // Verify the cart badge shows '1'
    const cartBadge = page.locator('.shopping_cart_badge');
    await expect(cartBadge).toBeVisible();
    await expect(cartBadge).toHaveText('1');

    // Verify the button label changed to 'Remove'
    const removeButton = page.locator('[data-test="remove-sauce-labs-backpack"]');
    await expect(removeButton).toBeVisible();
    await expect(removeButton).toHaveText('Remove');
  });

  test('should remove product from cart and hide the badge', async ({ page }) => {
    // First, add the product to cart
    const addToCartButton = page.locator('[data-test="add-to-cart-sauce-labs-backpack"]');
    await addToCartButton.click();

    // Verify the badge is visible with count 1
    const cartBadge = page.locator('.shopping_cart_badge');
    await expect(cartBadge).toBeVisible();
    await expect(cartBadge).toHaveText('1');

    // Click the remove button
    const removeButton = page.locator('[data-test="remove-sauce-labs-backpack"]');
    await removeButton.click();

    // Verify the badge is removed from the page
    await expect(cartBadge).not.toBeVisible();

    // Verify the button label changed back to 'Add to cart'
    await expect(addToCartButton).toBeVisible();
    await expect(addToCartButton).toHaveText('Add to cart');
  });

  test('should maintain accurate cart badge after multiple add/remove operations', async ({ page }) => {
    const addToCartButton = page.locator('[data-test="add-to-cart-sauce-labs-backpack"]');
    const removeButton = page.locator('[data-test="remove-sauce-labs-backpack"]');
    const cartBadge = page.locator('.shopping_cart_badge');

    // Add product to cart
    await addToCartButton.click();
    await expect(cartBadge).toHaveText('1');

    // Remove product from cart
    await removeButton.click();
    await expect(cartBadge).not.toBeVisible();

    // Add product to cart again
    await addToCartButton.click();
    await expect(cartBadge).toBeVisible();
    await expect(cartBadge).toHaveText('1');

    // Verify button shows Remove
    await expect(removeButton).toBeVisible();
    await expect(removeButton).toHaveText('Remove');
  });
});
